package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, k int
	fmt.Fscan(reader, &n, &k)

	a := make([]int, n+1)
	for i := 1; i <= n; i++ {
		fmt.Fscan(reader, &a[i])
	}

	adj := make([][]int, n+1)
	for i := 1; i <= n; i++ {
		adj[i] = []int{}
	}

	for i := 0; i < n-1; i++ {
		var u, v int
		fmt.Fscan(reader, &u, &v)
		adj[u] = append(adj[u], v)
		adj[v] = append(adj[v], u)
	}

	// We want to find the maximum possible minimum value among the first k nodes in a DFS preorder traversal.
	// The key insight: we can choose the root and the order of neighbors.
	// This is equivalent to: what is the maximum value X such that there exists a root and ordering where all first k nodes have value >= X?

	// Binary search on the answer.
	// For a given threshold X, can we find a root and ordering such that the first k nodes in DFS preorder all have a[i] >= X?

	// Actually, let's think differently.
	// The first k nodes in DFS preorder form a connected subgraph (a tree) that contains the root.
	// More precisely, they form a "prefix" of the DFS traversal.
	// 
	// Key observation: The set of first k nodes in a DFS preorder traversal of a tree, when we can choose root and neighbor order, 
	// must form a connected subtree of size k. Moreover, the root must be in this subtree, and the subtree must be "DFS-prefix compatible".
	//
	// Actually, a simpler characterization: 
	// We can achieve a set S of k nodes as the first k in DFS preorder if and only if:
	// 1. S is connected (forms a subtree).
	// 2. There exists a node r in S (the root) such that if we root the tree at r, then S is a "prefix-closed" set in the DFS order.
	//
	// But there's a known result for this problem: 
	// The answer is the maximum over all nodes v of the minimum value in the "k-1 closest" nodes to v in some sense? 
	// 
	// Let me reconsider. 
	// 
	// Actually, a well-known approach for this problem:
	// The first k nodes in DFS preorder, with optimal root and ordering, will be a connected set of k nodes.
	// And the minimum value in that set is the grade.
	// We want to maximize this minimum.
	//
	// So we want to find a connected subtree of size k that maximizes the minimum a[i] in it.
	// Wait, is that correct? Not exactly, because not every connected subtree of size k can be the first k in a DFS preorder.
	//
	// But actually, for any connected subtree of size k, we CAN make it the first k in a DFS preorder by choosing the right root and ordering.
	// Why? Pick any node in the subtree as root. Then order the neighbors so that we explore the subtree first. Since the subtree is connected, we can DFS through all k nodes before leaving.
	//
	// So the problem reduces to: find a connected subtree of size k that maximizes the minimum a[i] in it.
	//
	// How to solve this?
	// Binary search on the answer X. Check if there exists a connected subtree of size k where all nodes have a[i] >= X.
	//
	// To check: consider the graph induced by nodes with a[i] >= X. We need to know if there's a connected component of size >= k.
	// Because if there's a connected component of size >= k, we can pick any k nodes from it that form a connected subtree (which we can, since the component is connected, we can take a BFS/DFS tree of size k).
	//
	// So the check is: in the subgraph of nodes with a[i] >= X, is there a connected component of size >= k?
	//
	// This is efficient! We can do this with union-find or BFS/DFS.
	//
	// Binary search on X from 1 to max(a).
	// For each X, build the subgraph of nodes with a[i] >= X, and check if any connected component has size >= k.
	//
	// But n is up to 200,000, and binary search is O(log(max_a)) ~ 20 iterations.
	// Each check is O(n) with union-find or BFS.
	// Total: O(n log(max_a)) which is fine.

	// Let's implement binary search.

	lo, hi := 1, 0
	for i := 1; i <= n; i++ {
		if a[i] > hi {
			hi = a[i]
		}
	}

	// Check function: returns true if there exists a connected component of size >= k in the subgraph of nodes with a[i] >= X.
	check := func(X int) bool {
		// Use union-find or BFS. Let's use BFS/DFS for clarity, but union-find might be faster.
		// Let's use union-find.
		parent := make([]int, n+1)
		size := make([]int, n+1)
		for i := 1; i <= n; i++ {
			parent[i] = i
			if a[i] >= X {
				size[i] = 1
			} else {
				size[i] = 0
			}
		}

		find := func(x int) int {
			if parent[x] != x {
				parent[x] = find(parent[x])
			}
			return parent[x]
		}

		union := func(x, y int) {
			px := find(x)
			py := find(y)
			if px == py {
				return
			}
			if size[px] < size[py] {
				px, py = py, px
			}
			parent[py] = px
			size[px] += size[py]
		}

		for i := 1; i <= n; i++ {
			if a[i] < X {
				continue
			}
			for _, neighbor := range adj[i] {
				if a[neighbor] >= X {
					union(i, neighbor)
				}
			}
		}

		for i := 1; i <= n; i++ {
			if a[i] >= X && size[find(i)] >= k {
				return true
			}
		}
		return false
	}

	// Binary search for the maximum X such that check(X) is true.
	ans := 1
	for lo <= hi {
		mid := (lo + hi) / 2
		if check(mid) {
			ans = mid
			lo = mid + 1
		} else {
			hi = mid - 1
		}
	}

	fmt.Fprintln(writer, ans)
}
