	//
	// Then total[v] = (1 if a[v] >= x else 0) + sum_down[v] + up[v]
	//
	// We check if any total[v] >= k.
	//
	// This is O(n) per check, and we do O(log(max_a)) checks. Total O(n log(max_a)).
	//
	// Let's implement this.

	// Binary search on the answer
	lo, hi := 1, 1000000
	ans := 1

	for lo <= hi {
		mid := (lo + hi) / 2
		if check(n, k, a, adj, mid) {
			ans = mid
			lo = mid + 1
		} else {
			hi = mid - 1
		}
	}

	fmt.Fprintln(writer, ans)
}

func check(n, k int, a []int, adj [][]int, x int) bool {
	// Root at node 1 (index 1)
	parent := make([]int, n+1)
	children := make([][]int, n+1)
	for i := 1; i <= n; i++ {
		children[i] = []int{}
	}

	// BFS/DFS to set parent and children
	visited := make([]bool, n+1)
	visited[1] = true
	queue := []int{1}
	for len(queue) > 0 {
		v := queue[0]
		queue = queue[1:]
		for _, u := range adj[v] {
			if !visited[u] {
				visited[u] = true
				parent[u] = v
				children[v] = append(children[v], u)
				queue = append(queue, u)
			}
		}
	}

	// Compute down[v]
	down := make([]int, n+1)
	sumDown := make([]int, n+1)
	// Process in reverse BFS order (postorder)
	order := []int{}
	queue2 := []int{1}
	for len(queue2) > 0 {
		v := queue2[0]
		queue2 = queue2[1:]
		order = append(order, v)
		for _, c := range children[v] {
			queue2 = append(queue2, c)
		}
	}
	// Reverse order for postorder
	for i := len(order) - 1; i >= 0; i-- {
		v := order[i]
		sd := 0
		for _, c := range children[v] {
			sd += down[c]
		}
		sumDown[v] = sd
		if a[v] >= x {
			down[v] = 1 + sd
		} else {
			down[v] = 0
		}
	}

	// Compute up[v]
	up := make([]int, n+1)
	// Process in BFS order (preorder)
	for _, v := range order {
		for _, c := range children[v] {
			if a[v] >= x {
				up[c] = 1 + up[v] + (sumDown[v] - down[c])
			} else {
				up[c] = 0
			}
		}
	}

	// Check if any node has total >= k
	for v := 1; v <= n; v++ {
		total := 0
		if a[v] >= x {
			total = 1 + sumDown[v] + up[v]
		}
		if total >= k {
			return true
		}
	}
	return false
}
