	find = func(x int) int {
		if parent[x] != x {
			parent[x] = find(parent[x])
		}
		return parent[x]
	}

	union := func(x, y int) {
		px := find(x)
		py := find(y)
		if px == py {
			return
		}
		if size[px] < size[py] {
			px, py = py, px
		}
		parent[py] = px
		size[px] += size[py]
	}

	// Create list of nodes sorted by a[i] descending
	nodes := make([]int, n)
	for i := 0; i < n; i++ {
		nodes[i] = i + 1
	}
	sort.Slice(nodes, func(i, j int) bool {
		return a[nodes[i]] > a[nodes[j]]
	})

	answer := 0
	// Process nodes in descending order of a[i]
	for _, node := range nodes {
		active[node] = true
		// Union with active neighbors
		for _, neighbor := range adj[node] {
			if active[neighbor] {
				union(node, neighbor)
			}
		}
		// Check if the component containing this node has size >= k
		root := find(node)
		if size[root] >= k {
			answer = a[node]
			break
		}
	}

	fmt.Fprintln(writer, answer)
}
